// 10 % of the base premium, expressed as a tenth so that integer bases stay
// exact: 100 * 1.1 is 110.00000000000001 in binary floating point.
const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10;

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const withFirstInsuranceSurcharge = (base: number): number =>
  base + base / FIRST_INSURANCE_SURCHARGE_DIVISOR;
